/**
 * ambient.js — Sleep & Focus sounds, synthesised, never recorded.
 *
 * Like sfx.js, there is no audio file anywhere: every sound is a recipe
 * (noise beds through filters, with slow LFO movement; crickets and
 * temple bells are scheduled events). The same recipe drives two
 * builders — the live Web Audio graph below, and `renderRecipe`, a
 * plain-numbers renderer that exists so the sounds can be PROVED
 * audible in tests (scripts/verify_wave_a.mjs measures real RMS from
 * the rendered samples). A recipe that renders silence fails the gate.
 *
 * Noise itself is generated by `fillNoise` — one function, used by the
 * live buffers and by the numeric renderer alike.
 */

/* ------------------------------------------------------------- noise */
function mulberry(seed) {
  let a = seed >>> 0;
  return () => {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Fill `data` with white / pink (Kellet) / brown noise, deterministically. */
export function fillNoise(data, kind, seed = 7) {
  const rnd = mulberry(seed);
  if (kind === 'white') {
    for (let i = 0; i < data.length; i++) data[i] = rnd() * 2 - 1;
    return data;
  }
  if (kind === 'brown') {
    let last = 0;
    for (let i = 0; i < data.length; i++) {
      last = (last + 0.02 * (rnd() * 2 - 1)) * 0.9985;
      data[i] = Math.max(-1, Math.min(1, last * 3.2));
    }
    return data;
  }
  // pink — Paul Kellet's approximation
  let b0 = 0, b1 = 0, b2 = 0, b3 = 0, b4 = 0, b5 = 0, b6 = 0;
  for (let i = 0; i < data.length; i++) {
    const w = rnd() * 2 - 1;
    b0 = 0.99886 * b0 + w * 0.0555179; b1 = 0.99332 * b1 + w * 0.0750759;
    b2 = 0.96900 * b2 + w * 0.1538520; b3 = 0.86650 * b3 + w * 0.3104856;
    b4 = 0.55000 * b4 + w * 0.5329522; b5 = -0.7616 * b5 - w * 0.0168980;
    data[i] = (b0 + b1 + b2 + b3 + b4 + b5 + b6 + w * 0.5362) * 0.11;
    b6 = w * 0.115926;
  }
  return data;
}

/* ------------------------------------------------------------- recipes
   bed source: { kind, gain, filters: [{t, f, q}], lfoF: {rate, depth},
                 lfoG: {rate, depth} }
   events:     { type: 'chirp' | 'bell', every: seconds (render uses it
                 verbatim; live playback jitters it), gain } */
export const RECIPES = {
  rain: {
    name: 'Rain', desc: 'Steady rainfall, soft and even',
    beds: [
      { kind: 'pink', gain: 0.85, filters: [{ t: 'lowpass', f: 1150, q: 0.4 }], lfoF: { rate: 0.07, depth: 160 } },
      { kind: 'white', gain: 0.16, filters: [{ t: 'bandpass', f: 2900, q: 0.5 }] },
    ],
  },
  river: {
    name: 'River', desc: 'Moving water over stones',
    beds: [
      { kind: 'pink', gain: 0.8, filters: [{ t: 'bandpass', f: 520, q: 0.8 }], lfoF: { rate: 0.11, depth: 190 } },
      { kind: 'brown', gain: 0.5, filters: [{ t: 'lowpass', f: 320, q: 0.4 }] },
    ],
  },
  wind: {
    name: 'Wind', desc: 'Slow gusts through trees',
    beds: [
      { kind: 'pink', gain: 0.9, filters: [{ t: 'lowpass', f: 480, q: 0.6 }], lfoF: { rate: 0.05, depth: 330 }, lfoG: { rate: 0.043, depth: 0.3 } },
    ],
  },
  crickets: {
    name: 'Night crickets', desc: 'Cricket pulses over quiet night air',
    beds: [{ kind: 'pink', gain: 0.1, filters: [{ t: 'lowpass', f: 700, q: 0.4 }] }],
    events: { type: 'chirp', every: 0.95, gain: 0.5, freq: 4300 },
  },
  bells: {
    name: 'Temple bells', desc: 'A distant bell, now and then',
    beds: [{ kind: 'brown', gain: 0.16, filters: [{ t: 'lowpass', f: 260, q: 0.4 }] }],
    events: { type: 'bell', every: 7, gain: 0.65, freq: 392 },
  },
  white: {
    name: 'White noise', desc: 'Flat hiss — masks everything evenly',
    beds: [{ kind: 'white', gain: 0.42, filters: [] }],
  },
  pink: {
    name: 'Pink noise', desc: 'Softer hiss, like steady surf far away',
    beds: [{ kind: 'pink', gain: 0.75, filters: [] }],
  },
};
export const RECIPE_IDS = Object.keys(RECIPES);

/* ------------------------------------------- numeric renderer (tests)
   Renders a recipe to samples with the same numbers the live graph
   uses: fillNoise for beds, RBJ biquad coefficients for filters, the
   same LFO rates, and the same event shapes. Mono, seconds long. */
function biquadCoefs(t, f, q, sr) {
  const w = 2 * Math.PI * f / sr, cos = Math.cos(w), sin = Math.sin(w);
  const alpha = sin / (2 * q);
  let b0, b1, b2, a0, a1, a2;
  if (t === 'lowpass') { b0 = (1 - cos) / 2; b1 = 1 - cos; b2 = (1 - cos) / 2; a0 = 1 + alpha; a1 = -2 * cos; a2 = 1 - alpha; }
  else if (t === 'highpass') { b0 = (1 + cos) / 2; b1 = -(1 + cos); b2 = (1 + cos) / 2; a0 = 1 + alpha; a1 = -2 * cos; a2 = 1 - alpha; }
  else { b0 = alpha; b1 = 0; b2 = -alpha; a0 = 1 + alpha; a1 = -2 * cos; a2 = 1 - alpha; } // bandpass (constant 0 dB peak)
  return [b0 / a0, b1 / a0, b2 / a0, a1 / a0, a2 / a0];
}
export function renderRecipe(id, seconds = 12, sr = 44100) {
  const R = RECIPES[id];
  if (!R) return null;
  const n = Math.floor(seconds * sr);
  const out = new Float32Array(n);
  for (const bed of R.beds || []) {
    const src = fillNoise(new Float32Array(n), bed.kind, 11 + bed.kind.length);
    let x1 = 0, x2 = 0, y1 = 0, y2 = 0;
    const chains = (bed.filters || []).map((f) => ({ f, c: biquadCoefs(f.t, f.f, f.q || 0.7, sr), s: [0, 0, 0, 0] }));
    for (let i = 0; i < n; i++) {
      let v = src[i];
      for (const ch of chains) {
        if (bed.lfoF) { // refresh coefficients in blocks, as the live LFO moves the frequency
          if (i % 2048 === 0) {
            const fNow = ch.f.f + Math.sin(2 * Math.PI * bed.lfoF.rate * i / sr) * bed.lfoF.depth;
            ch.c = biquadCoefs(ch.f.t, Math.max(40, fNow), ch.f.q || 0.7, sr);
          }
        }
        const [b0, b1, b2, a1, a2] = ch.c, s = ch.s;
        const y = b0 * v + b1 * s[0] + b2 * s[1] - a1 * s[2] - a2 * s[3];
        s[1] = s[0]; s[0] = v; s[3] = s[2]; s[2] = y; v = y;
      }
      let g = bed.gain;
      if (bed.lfoG) g *= 1 - bed.lfoG.depth * (0.5 - 0.5 * Math.sin(2 * Math.PI * bed.lfoG.rate * i / sr));
      out[i] += v * g;
      x1 = x2; y1 = y2; // (kept for symmetry; chains hold their own state)
    }
  }
  if (R.events) {
    const ev = R.events, every = Math.floor(ev.every * sr);
    for (let start = 0; start < n; start += every) {
      if (ev.type === 'chirp') {
        for (let p = 0; p < 3; p++) {
          const ps = start + Math.floor(p * 0.07 * sr), len = Math.floor(0.055 * sr);
          for (let i = 0; i < len && ps + i < n; i++) {
            const t = i / sr, env = Math.min(1, t / 0.006) * Math.exp(-t * 38);
            out[ps + i] += Math.sin(2 * Math.PI * ev.freq * t) * env * ev.gain;
          }
        }
      } else { // bell: inharmonic partials, long decay; alternate two bells
        const base = (start / every) % 2 ? ev.freq * 1.335 : ev.freq;
        const partials = [[1, 1], [2.02, 0.55], [2.74, 0.32], [3.76, 0.18], [5.4, 0.07]];
        const len = Math.min(Math.floor(3.6 * sr), n - start);
        for (const [mult, amp] of partials) {
          for (let i = 0; i < len; i++) {
            const t = i / sr;
            out[start + i] += Math.sin(2 * Math.PI * base * mult * t) * Math.exp(-t * 1.5) * amp * ev.gain / partials.length * 2.2;
          }
        }
      }
    }
  }
  return out;
}
export function rms(samples) {
  if (!samples || !samples.length) return 0;
  let s = 0;
  for (let i = 0; i < samples.length; i++) s += samples[i] * samples[i];
  return Math.sqrt(s / samples.length);
}

/* --------------------------------------------------- live Web Audio */
let ctx = null, master = null;
const live = new Map();       // id -> { nodes..., gainNode, timer }
const bufCache = new Map();     // kind@rate -> AudioBuffer

export const supported = () => typeof window !== 'undefined' && !!(window.AudioContext || window.webkitAudioContext);
function ac() {
  if (!supported()) return null;
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    ctx = new AC();
    master = ctx.createGain(); master.gain.value = 0.9;
    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -18; comp.ratio.value = 6;
    master.connect(comp); comp.connect(ctx.destination);
  }
  if (ctx.state !== 'running') ctx.resume().catch(() => {});
  return ctx;
}
function noiseBuffer(kind) {
  const key = `${kind}@${ctx.sampleRate}`;
  if (bufCache.has(key)) return bufCache.get(key);
  const len = 4 * ctx.sampleRate;
  const buf = ctx.createBuffer(1, len, ctx.sampleRate);
  fillNoise(buf.getChannelData(0), kind, 11 + kind.length);
  bufCache.set(key, buf);
  return buf;
}
function scheduleEvents(id, R, dest) {
  const ev = R.events;
  const state = live.get(id);
  const strike = () => {
    if (!live.has(id) || !ctx) return;
    const t0 = ctx.currentTime + 0.03;
    if (ev.type === 'chirp') {
      for (let p = 0; p < 3; p++) {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'sine'; o.frequency.value = ev.freq * (0.98 + Math.random() * 0.04);
        const s = t0 + p * 0.07;
        g.gain.setValueAtTime(0, s);
        g.gain.linearRampToValueAtTime(ev.gain, s + 0.006);
        g.gain.exponentialRampToValueAtTime(0.0008, s + 0.055);
        o.connect(g); g.connect(dest); o.start(s); o.stop(s + 0.07);
      }
    } else {
      const count = (state.strikes = (state.strikes || 0) + 1);
      const base = count % 2 ? ev.freq * 1.335 : ev.freq;
      for (const [mult, amp] of [[1, 1], [2.02, 0.55], [2.74, 0.32], [3.76, 0.18], [5.4, 0.07]]) {
        const o = ctx.createOscillator(), g = ctx.createGain();
        o.type = 'sine'; o.frequency.value = base * mult;
        g.gain.setValueAtTime(ev.gain * amp * 0.44, t0);
        g.gain.exponentialRampToValueAtTime(0.0008, t0 + 3.6);
        o.connect(g); g.connect(dest); o.start(t0); o.stop(t0 + 3.7);
      }
    }
    state.timer = setTimeout(strike, ev.every * 1000 * (0.75 + Math.random() * 0.6));
  };
  strike();
}

export function play(id, volume = 0.8) {
  const R = RECIPES[id];
  if (!R) return { ok: false, why: 'no such sound' };
  if (!ac()) return { ok: false, why: 'this browser has no Web Audio' };
  stop(id);
  try {
    const gainNode = ctx.createGain();
    gainNode.gain.value = volume;
    gainNode.connect(master);
    const nodes = [];
    for (const bed of R.beds || []) {
      const srcNode = ctx.createBufferSource();
      srcNode.buffer = noiseBuffer(bed.kind); srcNode.loop = true;
      let head = srcNode;
      for (const f of bed.filters || []) {
        const bi = ctx.createBiquadFilter();
        bi.type = f.t; bi.frequency.value = f.f; bi.Q.value = f.q || 0.7;
        head.connect(bi); head = bi;
        if (bed.lfoF) {
          const lfo = ctx.createOscillator(), lg = ctx.createGain();
          lfo.frequency.value = bed.lfoF.rate; lg.gain.value = bed.lfoF.depth;
          lfo.connect(lg); lg.connect(bi.frequency); lfo.start(); nodes.push(lfo);
        }
      }
      const bg = ctx.createGain(); bg.gain.value = bed.gain;
      head.connect(bg); bg.connect(gainNode);
      if (bed.lfoG) {
        const lfo = ctx.createOscillator(), lg = ctx.createGain();
        lfo.frequency.value = bed.lfoG.rate; lg.gain.value = bed.gain * bed.lfoG.depth;
        bg.gain.value = bed.gain * (1 - bed.lfoG.depth / 2);
        lfo.connect(lg); lg.connect(bg.gain); lfo.start(); nodes.push(lfo);
      }
      srcNode.start();
      nodes.push(srcNode);
    }
    live.set(id, { gainNode, nodes, timer: null, strikes: 0 });
    if (R.events) scheduleEvents(id, R, gainNode);
    return { ok: true };
  } catch (e) {
    return { ok: false, why: `graph failed: ${e.message}` };
  }
}
export function setVolume(id, v) {
  const s = live.get(id);
  if (s && ctx) s.gainNode.gain.setTargetAtTime(v, ctx.currentTime, 0.1);
}
export function stop(id) {
  const s = live.get(id);
  if (!s) return;
  live.delete(id);
  if (s.timer) clearTimeout(s.timer);
  try { s.gainNode.disconnect(); } catch { /* already gone */ }
  for (const n of s.nodes) { try { n.stop(); } catch { /* oscillators may not have started */ } try { n.disconnect(); } catch { /* noop */ } }
}
export function playingIds() { return [...live.keys()]; }
/** Fade everything out over `sec` seconds, then stop. For the sleep timer. */
export function fadeOutAll(sec = 3) {
  if (!ctx || !master) return;
  const t = ctx.currentTime;
  master.gain.cancelScheduledValues(t);
  master.gain.setValueAtTime(master.gain.value, t);
  master.gain.linearRampToValueAtTime(0.0001, t + sec);
  setTimeout(() => { for (const id of playingIds()) stop(id); if (master) master.gain.value = 0.9; }, sec * 1000 + 60);
}
